#!/usr/bin/env bash
set -Eeuo pipefail

ACTION="${1:-install}"
CTR="${OPENMW_CONTAINER:-openmw_builder}"
DEV="${TSP_DEVICE:-root@192.168.1.25}"

SRC=/root/openmw-0.51-tsp-src
BUILD=/root/openmw-0.51-tsp-build
PACKAGE=/root/openmw-0.51-tsp-package
SCENE_CPP="$SRC/apps/openmw/mwworld/scene.cpp"
VIS_CPP="$SRC/apps/openmw/mwrender/interiorvisibility.cpp"
ANIM="$SRC/apps/openmw/mwrender/animation.cpp"
BUILT="$BUILD/openmw"
PACKAGED="$PACKAGE/bin/openmw-0.51"

ROOT=/mnt/SDCARD/data/ports/openmw51
REMOTE_BIN="$ROOT/bin/openmw-0.51"
LUA_DIR="$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid"
LIVE_LUA="$LUA_DIR/visgrid.lua"
V24_PROFILE="$LUA_DIR/v24_profiles/visgrid-v24-room-residency.lua"
V27_DIR="$LUA_DIR/v27_profiles"
V27_PROFILE="$V27_DIR/visgrid-v27-adaptive-clutter.lua"
REMOTE_TMP_BIN=/tmp/openmw-0.51.v27-adaptive-clutter

DL="$HOME/Downloads"
HOST_BIN="$DL/openmw-0.51-v27-adaptive-clutter"
STATE="$DL/openmw51-visgrid-v27-adaptive-clutter.state"
STAMP="$(date +%Y%m%d-%H%M%S)"
LOG="$DL/openmw51-visgrid-v27-adaptive-clutter-$STAMP.log"
TMP="$(mktemp -d "$DL/.v27-adaptive-clutter.XXXXXX")"
SOURCE_BACKUP=""
DEVICE_BACKUP=""
DEVICE_DEPLOY_STARTED=0
LAUNCHER=""

cleanup(){ rm -rf "$TMP" 2>/dev/null || true; }
trap cleanup EXIT

die(){ echo "ERROR: $*" >&2; exit 1; }

ensure_docker(){
    command -v docker >/dev/null 2>&1 || die "docker not found"
    docker inspect "$CTR" >/dev/null 2>&1 || die "Docker container '$CTR' not found"
    if [ "$(docker inspect -f '{{.State.Running}}' "$CTR")" != true ]; then
        docker start "$CTR" >/dev/null
    fi
}

ensure_ssh(){
    command -v ssh >/dev/null 2>&1 || die "ssh not found"
    command -v scp >/dev/null 2>&1 || die "scp not found"
    ssh -o BatchMode=yes -o ConnectTimeout=8 "$DEV" true || die "cannot reach $DEV"
}

game_closed(){
    ! ssh "$DEV" "pgrep -af 'openmw-0\\.51|/openmw([[:space:]]|$)' 2>/dev/null" | grep -v pgrep
}

locate_launcher(){
    ssh "$DEV" 'bash -s' <<'REMOTE'
for p in \
  /mnt/SDCARD/Roms/PORTS/Morrowind_51.sh \
  /mnt/SDCARD/Emus/PORTS/../../Roms/PORTS/Morrowind_51.sh \
  /mnt/SDCARD/roms/ports/Morrowind_51.sh
 do
   [ -f "$p" ] || continue
   readlink -f "$p" 2>/dev/null || printf '%s\n' "$p"
   exit 0
 done
exit 1
REMOTE
}

restore_device(){
    [ -n "${DEVICE_BACKUP:-}" ] || return 0
    ssh "$DEV" "bash -s" <<REMOTE
set -e
B='$DEVICE_BACKUP'
test -s "\$B/openmw-0.51.before"
test -s "\$B/visgrid.lua.before"
test -s "\$B/launcher.before"
cp -pf "\$B/openmw-0.51.before" '$REMOTE_BIN'
cp -pf "\$B/visgrid.lua.before" '$LIVE_LUA'
cp -pf "\$B/launcher.before" '$LAUNCHER'
if [ -f "\$B/v27-profile.existed" ]; then
  mkdir -p '$V27_DIR'
  cp -pf "\$B/v27-profile.before" '$V27_PROFILE'
else
  rm -f '$V27_PROFILE'
fi
chmod 755 '$REMOTE_BIN' '$LAUNCHER'
sync
REMOTE
}

collect_latest(){
    ensure_ssh
    OUT="$DL/openmw51-visgrid-v27-adaptive-clutter-validation-$STAMP.txt"
    ssh "$DEV" "ROOT='$ROOT' bash -s" <<'REMOTE' > "$OUT"
set +e
printf '%s\n' '============================================================'
printf '%s\n' 'OPENMW 0.51 V27 ADAPTIVE CLUTTER MANUAL CAPTURE'
printf '%s\n' '============================================================'
date
printf '\n===== IDENTITY =====\n'
sha256sum "$ROOT/bin/openmw-0.51" \
  "$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/visgrid.lua" 2>/dev/null || true

RAW=/tmp/v27-manual-capture.$$
: > "$RAW"
for f in "$ROOT/openmw_051_log.txt" "$ROOT/config-0.51/openmw.log" "$ROOT/openmw.log"; do
  [ -s "$f" ] || continue
  tail -n 12000 "$f" >> "$RAW"
done

printf '\n===== V27 CLUTTER NEIGHBORHOOD =====\n'
grep -E '\[TSP_VISGRID_V27\] clutter|\[TSP_ROOMOBJ_V27\]' "$RAW" | tail -120 || true

printf '\n===== FOG / VISGRID STATE =====\n'
grep -E 'TSP_INTERIOR_VISGRID_051_V3_PERCENTILE_FOG|TSP_INTERIOR_VISGRID_051_V4_CULLFOG|TSP_INTERIOR_VISGRID_051_V4B_BORDERFOG|\[TSP_VISGRID_V24\]|\[TSP_VISGRID_V11\].*reject=' "$RAW" | tail -100 || true

printf '\n===== CELL / SECTOR EVENTS =====\n'
grep -E 'enter interior|topology sector=|sector switch|Unloading cell|unload-purge' "$RAW" | tail -120 || true

printf '\n===== ERRORS =====\n'
grep -Ei 'Bad LiveCellRef cast|failed to render|Lua.*error|segfault|fatal|exception|assert|TSP_VISGRID_V27.*error' "$RAW" | tail -120 || true

printf '\n===== EXIT TAIL =====\n'
for f in "$ROOT/openmw_051_log.txt" "$ROOT/config-0.51/openmw.log"; do
  [ -s "$f" ] || continue
  echo "--- $f ---"
  tail -n 80 "$f"
done

printf '\n===== PERF TAIL =====\n'
[ ! -f "$ROOT/openmw51_perf_latest.txt" ] || tail -100 "$ROOT/openmw51_perf_latest.txt"
rm -f "$RAW"
REMOTE
    echo "Saved: $OUT"
    echo
    grep -E '\[TSP_VISGRID_V27\] clutter|\[TSP_ROOMOBJ_V27\]' "$OUT" | tail -20 || true
}

rollback_all(){
    [ -s "$STATE" ] || die "state file missing: $STATE"
    # shellcheck disable=SC1090
    . "$STATE"
    ensure_docker
    ensure_ssh
    game_closed || die "OpenMW is running"
    docker exec "$CTR" bash -lc "set -e; cp -pf '$SOURCE_BACKUP/scene.cpp' '$SCENE_CPP'; cp -pf '$SOURCE_BACKUP/interiorvisibility.cpp' '$VIS_CPP'; cp -pf '$SOURCE_BACKUP/animation.cpp' '$ANIM'"
    restore_device
    echo "ROLLBACK COMPLETE"
}

case "$ACTION" in
    collect) collect_latest; exit 0 ;;
    rollback) rollback_all; exit 0 ;;
    install) ;;
    *) die "Usage: $0 [install|collect|rollback]" ;;
esac

exec > >(tee "$LOG") 2>&1

on_error(){
    rc=$?
    trap - ERR
    set +e
    echo
    echo "===== V27 STOPPED SAFELY (rc=$rc) ====="
    if [ -n "$SOURCE_BACKUP" ]; then
        docker exec "$CTR" bash -lc "cp -pf '$SOURCE_BACKUP/scene.cpp' '$SCENE_CPP'; cp -pf '$SOURCE_BACKUP/interiorvisibility.cpp' '$VIS_CPP'; cp -pf '$SOURCE_BACKUP/animation.cpp' '$ANIM'" >/dev/null 2>&1 || true
    fi
    if [ "$DEVICE_DEPLOY_STARTED" = 1 ] && [ -n "$DEVICE_BACKUP" ]; then
        restore_device >/dev/null 2>&1 || true
    fi
    echo "Log preserved: $LOG"
    exit "$rc"
}
trap on_error ERR

echo "============================================================"
echo "OPENMW 0.51 — VISGRID V27 ADAPTIVE CLUTTER"
echo "============================================================"
echo "V26 hard scene deletion retained for clutter."
echo "Static architecture bypasses VISGRID completely."
echo "Activators are kept with the structural tier."
echo "Clutter: current room + bounded nearby sectors by room kind."
echo "V24 ray/depth/fog profile restored."
echo "Normal-exit automatic capture removed; collect is manual only."
echo "============================================================"

ensure_docker
ensure_ssh
LAUNCHER="$(locate_launcher)"
[ -n "$LAUNCHER" ] || die "could not locate Morrowind_51.sh"

echo
echo "===== 1/9 PRE-FLIGHT ====="
game_closed || die "OpenMW is running. Exit normally and rerun."

docker exec "$CTR" bash -lc "set -e; test -s '$SCENE_CPP'; test -s '$VIS_CPP'; test -s '$ANIM'; test -s '$BUILT'; grep -Fq 'TSP_ROOM_OBJECT_CURRENT_SECTOR_051_V26' '$SCENE_CPP'; grep -Fq '[TSP_ROOMOBJ_V26]' '$SCENE_CPP'; grep -Fq 'TSP_ROOM_OBJECT_CURRENT_SECTOR_051_V26' '$VIS_CPP'; grep -Fq 'TSP_VISGRID_ROOM_RESIDENCY_051_V24' '$ANIM'; ! grep -Fq 'TSP_ROOM_OBJECT_ADAPTIVE_051_V27' '$SCENE_CPP'; ! grep -Fq 'mPtr.get<ESM::Static>()' '$ANIM'"
ssh "$DEV" "set -e; test -s '$REMOTE_BIN'; test -s '$LIVE_LUA'; test -s '$V24_PROFILE'; test -s '$LAUNCHER'; grep -Fq 'TSP_VISGRID_LUA_V26_CURRENT_SECTOR_ONLY' '$LIVE_LUA'; grep -Fq 'TSP_VISGRID_LUA_V24_ROOM_RESIDENCY' '$V24_PROFILE'"
PRE_SHA="$(ssh "$DEV" "sha256sum '$REMOTE_BIN'" | awk '{print $1}')"
PRE_LUA_SHA="$(ssh "$DEV" "sha256sum '$LIVE_LUA'" | awk '{print $1}')"
V24_SHA="$(ssh "$DEV" "sha256sum '$V24_PROFILE'" | awk '{print $1}')"
echo "Current binary SHA: $PRE_SHA"
echo "Current V26 Lua:    $PRE_LUA_SHA"
echo "Stored V24 profile: $V24_SHA"

echo
echo "===== 2/9 BACKUP SOURCE + PULL V24 PROFILE / LIVE LAUNCHER ====="
SOURCE_BACKUP="$SRC/.tsp-051-source-backups/visgrid-v27-adaptive-clutter-$STAMP"
docker exec "$CTR" bash -lc "set -e; mkdir -p '$SOURCE_BACKUP'; cp -pf '$SCENE_CPP' '$SOURCE_BACKUP/scene.cpp'; cp -pf '$VIS_CPP' '$SOURCE_BACKUP/interiorvisibility.cpp'; cp -pf '$ANIM' '$SOURCE_BACKUP/animation.cpp'; sha256sum '$SOURCE_BACKUP/'*"
scp -q "$DEV:$V24_PROFILE" "$TMP/visgrid.v24.lua"
scp -q "$DEV:$LAUNCHER" "$TMP/Morrowind_51.v26.sh"
[ "$(sha256sum "$TMP/visgrid.v24.lua" | awk '{print $1}')" = "$V24_SHA" ] || die "V24 profile pull SHA mismatch"

echo
echo "===== 3/9 PATCH C++ ADAPTIVE CLUTTER / STRUCTURE SAFETY / TEARDOWN ====="
base64 -d > "$TMP/v27_cpp_patch.py" <<'V27_CPP_B64'

V27_CPP_B64
python3 -m py_compile "$TMP/v27_cpp_patch.py"
docker cp "$TMP/v27_cpp_patch.py" "$CTR:/tmp/v27_cpp_patch.py"
docker exec "$CTR" python3 /tmp/v27_cpp_patch.py "$SCENE_CPP" "$VIS_CPP" "$ANIM"
docker exec "$CTR" rm -f /tmp/v27_cpp_patch.py

docker exec "$CTR" bash -lc "set -e; grep -Fq 'TSP_ROOM_OBJECT_ADAPTIVE_051_V27' '$SCENE_CPP'; grep -Fq '[TSP_ROOMOBJ_V27]' '$SCENE_CPP'; grep -Fq 'fallbackOwnership = 260.f' '$VIS_CPP'; grep -Fq '!tspDiagActor && !tspDiagDoor && !tspIsStatic' '$ANIM'; grep -Fq 'unload-purge parked=' '$SCENE_CPP'; ! grep -Fq 'mPtr.get<ESM::Static>()' '$ANIM'"

echo
echo "===== 4/9 GENERATE V27 LUA FROM STORED V24 + PATCH LAUNCHER ====="
base64 -d > "$TMP/v27_lua_patch.py" <<'V27_LUA_B64'

V27_LUA_B64
base64 -d > "$TMP/v27_launcher_patch.py" <<'V27_LAUNCH_B64'

V27_LAUNCH_B64
python3 -m py_compile "$TMP/v27_lua_patch.py" "$TMP/v27_launcher_patch.py"
python3 "$TMP/v27_lua_patch.py" "$TMP/visgrid.v24.lua" "$TMP/visgrid.v27.lua"
python3 "$TMP/v27_launcher_patch.py" "$TMP/Morrowind_51.v26.sh" "$TMP/Morrowind_51.v27.sh"
chmod +x "$TMP/Morrowind_51.v27.sh"
bash -n "$TMP/Morrowind_51.v27.sh"

PARSER=""
for x in texlua lua luajit; do
    command -v "$x" >/dev/null 2>&1 && { PARSER="$x"; break; }
done
if [ -n "$PARSER" ]; then
    cat > "$TMP/parse.lua" <<'LUA'
local f,e=loadfile(arg[1]); if not f then error(e) end; print('LUA_PARSE_PASS '..arg[1])
LUA
    "$PARSER" "$TMP/parse.lua" "$TMP/visgrid.v27.lua"
fi
V27_LUA_SHA="$(sha256sum "$TMP/visgrid.v27.lua" | awk '{print $1}')"
echo "V27 Lua SHA: $V27_LUA_SHA"

echo
echo "===== 5/9 BUILD ====="
BUILD_LOG=/root/openmw51-visgrid-v27-adaptive-clutter-$STAMP.log
set +e
docker exec "$CTR" bash -lc "set -o pipefail; cd '$BUILD'; cmake --build . --target openmw --parallel '${OPENMW_JOBS:-2}' 2>&1 | tee '$BUILD_LOG'"
RC=$?
set -e
if [ "$RC" -ne 0 ]; then
    echo "BUILD FAILED — last 220 lines:"
    docker exec "$CTR" bash -lc "tail -n 220 '$BUILD_LOG' || true"
    false
fi

echo
echo "===== 6/9 PACKAGE / MULTI-VERIFY ====="
docker exec "$CTR" bash -lc "set -e; test -s '$BUILT'; mkdir -p '$(dirname "$PACKAGED")'; install -m 755 '$BUILT' '$PACKAGED'; file '$PACKAGED'; file '$PACKAGED' | grep -Eq 'ARM aarch64|ARM64|AArch64'; sha256sum '$PACKAGED'; strings '$PACKAGED' | grep -E 'TSP_ROOMOBJ_V27|TSP_ROOM_OBJECT_ADAPTIVE_051_V27|TSP_OBJECT_DIAG_051_V1' | sort -u | head -50 || true"
NEW_SHA="$(docker exec "$CTR" sha256sum "$PACKAGED" | awk '{print $1}')"
[ "$NEW_SHA" != "$PRE_SHA" ] || die "rebuilt hash did not change"
docker cp "$CTR:$PACKAGED" "$HOST_BIN"
chmod +x "$HOST_BIN"
[ "$(sha256sum "$HOST_BIN" | awk '{print $1}')" = "$NEW_SHA" ] || die "Docker->Ubuntu SHA mismatch"
file "$HOST_BIN"
sha256sum "$HOST_BIN"

echo
echo "===== 7/9 VERIFY MANUAL-COLLECT / NO AUTO-EXIT CAPTURE ====="
! grep -Fq '# >>> TSP_VISGRID_V24_AUTO_CAPTURE BEGIN' "$TMP/Morrowind_51.v27.sh"
! grep -Fq 'tsp_visgrid_v24_capture.sh" "$OPENMW_EXIT_CODE"' "$TMP/Morrowind_51.v27.sh"
grep -Fq 'v27_profiles/visgrid-v27-adaptive-clutter.lua' "$TMP/Morrowind_51.v27.sh"
grep -Fq 'TSP_VISGRID_LUA_V27_ADAPTIVE_CLUTTER' "$TMP/visgrid.v27.lua"
echo "PASS: launcher will not run synchronous capture after OpenMW exits."
echo "PASS: ./$(basename "$0") collect is host-side/manual only."

echo
echo "===== 8/9 DEVICE BACKUP / INSTALL ====="
DEVICE_BACKUP="$ROOT/backups/visgrid-v27-adaptive-clutter-$STAMP"
ssh "$DEV" "bash -s" <<REMOTE_BACKUP
set -e
B='$DEVICE_BACKUP'
mkdir -p "\$B"
cp -pf '$REMOTE_BIN' "\$B/openmw-0.51.before"
cp -pf '$LIVE_LUA' "\$B/visgrid.lua.before"
cp -pf '$LAUNCHER' "\$B/launcher.before"
if [ -f '$V27_PROFILE' ]; then touch "\$B/v27-profile.existed"; cp -pf '$V27_PROFILE' "\$B/v27-profile.before"; fi
sha256sum "\$B/openmw-0.51.before" "\$B/visgrid.lua.before" "\$B/launcher.before"
REMOTE_BACKUP
DEVICE_DEPLOY_STARTED=1

scp -q "$HOST_BIN" "$DEV:$REMOTE_TMP_BIN"
scp -q "$TMP/visgrid.v27.lua" "$DEV:/tmp/visgrid-v27.lua"
scp -q "$TMP/Morrowind_51.v27.sh" "$DEV:/tmp/Morrowind_51.v27.sh"
ssh "$DEV" "bash -s" <<REMOTE_INSTALL
set -e
mkdir -p '$V27_DIR'
test "\$(sha256sum '$REMOTE_TMP_BIN' | awk '{print \$1}')" = '$NEW_SHA'
test "\$(sha256sum /tmp/visgrid-v27.lua | awk '{print \$1}')" = '$V27_LUA_SHA'
install -m 755 '$REMOTE_TMP_BIN' '$REMOTE_BIN'
install -m 644 /tmp/visgrid-v27.lua '$V27_PROFILE'
install -m 644 /tmp/visgrid-v27.lua '$LIVE_LUA'
install -m 755 /tmp/Morrowind_51.v27.sh '$LAUNCHER'
rm -f '$REMOTE_TMP_BIN' /tmp/visgrid-v27.lua /tmp/Morrowind_51.v27.sh
sync
test "\$(sha256sum '$REMOTE_BIN' | awk '{print \$1}')" = '$NEW_SHA'
test "\$(sha256sum '$LIVE_LUA' | awk '{print \$1}')" = '$V27_LUA_SHA'
bash -n '$LAUNCHER'
grep -Fq 'v27_profiles/visgrid-v27-adaptive-clutter.lua' '$LAUNCHER'
grep -Fq 'TSP_VISGRID_LUA_V27_ADAPTIVE_CLUTTER' '$LIVE_LUA'
! grep -Fq '# >>> TSP_VISGRID_V24_AUTO_CAPTURE BEGIN' '$LAUNCHER'
! grep -Fq 'export TSP_OBJECT_DIAG=1' '$LAUNCHER'
echo 'Installed binary:'; sha256sum '$REMOTE_BIN'
echo 'Installed Lua:'; sha256sum '$LIVE_LUA'
REMOTE_INSTALL

echo
echo "===== 9/9 STATE ====="
cat > "$STATE" <<EOF_STATE
SOURCE_BACKUP='$SOURCE_BACKUP'
DEVICE_BACKUP='$DEVICE_BACKUP'
LAUNCHER='$LAUNCHER'
PRE_DEVICE_SHA='$PRE_SHA'
FIX_DEVICE_SHA='$NEW_SHA'
PRE_LUA_SHA='$PRE_LUA_SHA'
V24_PROFILE_SHA='$V24_SHA'
V27_LUA_SHA='$V27_LUA_SHA'
HOST_BIN='$HOST_BIN'
EOF_STATE

trap - ERR

echo
echo "============================================================"
echo "V27 ADAPTIVE CLUTTER INSTALLED"
echo "============================================================"
echo "CLUTTER ROOM POLICY:"
echo "  small_room         current + 1 nearby, base 240"
echo "  room               current + 1 nearby, base 330"
echo "  large_open         current + up to 3 nearby, base 650"
echo "  corridor           current + up to 3 nearby, base 600"
echo "  vertical_connector current + up to 2 nearby, base 450"
echo "  <=3-sector maps    up to 2 extras within at least 700"
echo "  large/corridor/connector TARGET rooms get modest extra prewake reach"
echo
echo "OBJECT OWNERSHIP:"
echo "  direct XY room bleed = 0"
echo "  vertical shelf/table slack = 110"
echo "  nearest-sector ownership fallback = 260 (NOT a player keep radius)"
echo "  truly unmapped objects = fail OPEN / stay present"
echo
echo "STRUCTURE:"
echo "  ESM Static walls/floors/stairs/etc = no VISGRID callback"
echo "  doors/actors = unchanged / always outside this system"
echo "  Activators = never hard-parked"
echo
echo "FOG/RAYS:"
echo "  generated from stored V24 profile"
echo "  normal 5/6 ray sensor restored"
echo "  load-safe hold = 1.0s"
echo
echo "EXIT:"
echo "  synchronous launcher auto-capture = REMOVED"
echo "  parked paging bookkeeping = purged before cell teardown"
echo "  diagnostics = manual collect only"
echo
echo "After one useful run:"
echo "  cd ~/Downloads"
echo "  ./apply_openmw51_tsp_visgrid_v27_adaptive_clutter.sh collect"
echo
echo "Rollback:"
echo "  ./apply_openmw51_tsp_visgrid_v27_adaptive_clutter.sh rollback"
echo "============================================================"
